-- Pebble: Spielerprofile, Freunde, Anmelden mit Spielernamen
create table if not exists public.pebble_profiles (user_id uuid primary key references auth.users(id) on delete cascade, name text not null, code text, ch text, outfit jsonb, level int default 1, about text default '', updated_at timestamptz not null default now());
alter table public.pebble_profiles enable row level security;
drop policy if exists "profile alle lesen" on public.pebble_profiles;
create policy "profile alle lesen" on public.pebble_profiles for select to authenticated using (true);
drop policy if exists "profile eigenes anlegen" on public.pebble_profiles;
create policy "profile eigenes anlegen" on public.pebble_profiles for insert to authenticated with check (user_id = auth.uid());
drop policy if exists "profile eigenes aendern" on public.pebble_profiles;
create policy "profile eigenes aendern" on public.pebble_profiles for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
create table if not exists public.pebble_friends (a uuid not null references auth.users(id) on delete cascade, b uuid not null references auth.users(id) on delete cascade, status text not null default 'pending' check (status in ('pending','accepted')), created_at timestamptz not null default now(), primary key (a,b), check (a <> b));
alter table public.pebble_friends enable row level security;
drop policy if exists "freunde lesen" on public.pebble_friends;
create policy "freunde lesen" on public.pebble_friends for select to authenticated using (a = auth.uid() or b = auth.uid());
drop policy if exists "freunde anfragen" on public.pebble_friends;
create policy "freunde anfragen" on public.pebble_friends for insert to authenticated with check (a = auth.uid() and status = 'pending');
drop policy if exists "freunde annehmen" on public.pebble_friends;
create policy "freunde annehmen" on public.pebble_friends for update to authenticated using (b = auth.uid()) with check (b = auth.uid());
drop policy if exists "freunde loeschen" on public.pebble_friends;
create policy "freunde loeschen" on public.pebble_friends for delete to authenticated using (a = auth.uid() or b = auth.uid());
drop policy if exists "pebble freunde besuchen" on public.pebble_saves;
create policy "pebble freunde besuchen" on public.pebble_saves for select to authenticated using (exists (select 1 from public.pebble_friends f where f.status = 'accepted' and ((f.a = auth.uid() and f.b = pebble_saves.user_id) or (f.b = auth.uid() and f.a = pebble_saves.user_id))));
create table if not exists public.pebble_logins (user_id uuid primary key references auth.users(id) on delete cascade, name_lower text unique not null, email text not null, login_hash text not null);
alter table public.pebble_logins enable row level security;
drop policy if exists "login eigenes anlegen" on public.pebble_logins;
create policy "login eigenes anlegen" on public.pebble_logins for insert to authenticated with check (user_id = auth.uid());
drop policy if exists "login eigenes aendern" on public.pebble_logins;
create policy "login eigenes aendern" on public.pebble_logins for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
create or replace function public.pebble_login_email(n text, h text) returns text language sql stable security definer set search_path = public as $$ select email from public.pebble_logins where name_lower = lower(n) and login_hash = h limit 1 $$;
grant execute on function public.pebble_login_email(text, text) to anon, authenticated;
